from pydantic import BaseModel, Field, field_validator
HADAMARD_TYPES = frozenset({'hadamard','random_hadamard','inplace_quarot_hadamard','inplace_hadamard','inplace_random'})
class RotationConfig(BaseModel):
    hadamard_type: str = Field(default='hadamard')
    @field_validator('hadamard_type')
    @classmethod
    def _v(cls, v):
        if v not in HADAMARD_TYPES:
            raise ValueError('Unsupported hadamard_type: %r' % v)
        return v
try:
